/**
 * Shared closed-schema primitives. All object schemas are `.strict()`: unknown fields are
 * rejected, never stripped. Amounts are base-unit decimal strings; floating point never
 * appears in economic fields.
 */
import { z } from 'zod';
import { DIGEST_PATTERN } from '../canonical/digest.ts';

export const UUID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;

/** Opaque lowercase UUID generated by the service. */
export const Uuid = z.string().regex(UUID_PATTERN, 'expected lowercase UUID');
export const DigestString = z.string().regex(DIGEST_PATTERN, 'expected sha256:<64 hex>');
/** Non-negative base-unit integer amount as a canonical decimal string. */
export const BaseUnitAmount = z.string().regex(/^(0|[1-9][0-9]{0,77})$/, 'expected base-unit integer string');
export const NonNegativeInt = z.number().int().nonnegative().max(Number.MAX_SAFE_INTEGER);
export const PositiveInt = z.number().int().positive().max(Number.MAX_SAFE_INTEGER);
/** Fencing epochs and sequences are monotonically increasing non-negative integers. */
export const FencingEpoch = NonNegativeInt;
export const Sequence = NonNegativeInt;
/** Virtual milliseconds are integers and never wall time. */
export const VirtualMs = NonNegativeInt;
/** Bounded opaque identifier/label text (no control characters). */
export const BoundedText = (max: number) =>
  z
    .string()
    .min(1)
    .max(max)
    .refine((s) => !/[\u0000-\u001f\u007f]/.test(s), 'control characters are not permitted');
export const CommitSha = z.string().regex(/^[0-9a-f]{40}([0-9a-f]{24})?$/, 'expected git object id');
/** Revision identifiers such as evaluator/adapter/profile revisions: `name@semver-ish`. */
export const RevisionId = z
  .string()
  .regex(/^[a-z0-9][a-z0-9._-]{0,63}@[0-9A-Za-z.+-]{1,64}$/, 'expected name@revision');

/** Schema version string `<major>.<minor>`. */
export const SCHEMA_VERSION_PATTERN = /^(0|[1-9][0-9]{0,3})\.(0|[1-9][0-9]{0,3})$/;

export function schemaVersionLiteral<const V extends string>(version: V) {
  return z.literal(version);
}

export { z };
